-- Oracle EBS R12 -> canonical PAYMENT (ORACLE_EBS). Generated by tools/build_silver_sql.py.
SELECT 'ORACLE_EBS' AS SOURCE_SLOT, 'Oracle EBS R12' AS SOURCE_SYSTEM, 'ORACLE_EBS' AS COMPANY_CODE, i.INVOICE_NUM AS INVOICE_ID, i.VENDOR_ID::STRING AS SUPPLIER_ID, i.INVOICE_DATE,
  DATEADD(day, 45, i.INVOICE_DATE) AS DUE_DATE, c.CHECK_DATE AS PAYMENT_DATE, p.AMOUNT, 0::FLOAT AS DISCOUNT_TAKEN, c.CURRENCY_CODE AS CURRENCY,
  i.TERMS_NAME AS PAYMENT_TERMS
FROM {{ source('src_oracle_ebs', 'ap_invoice_payments_all') }} p JOIN {{ source('src_oracle_ebs', 'ap_invoices_all') }} i ON i.INVOICE_ID = p.INVOICE_ID JOIN {{ source('src_oracle_ebs', 'ap_checks_all') }} c ON c.CHECK_ID = p.CHECK_ID
